#include <vector>
#include <numeric>

class Solution {
public:
    int countRotationsWithKAdjacentPairs(std::vector<int>& nums, int k) {
        int n = nums.size();
        if (n <= 1) return (k == 0) ? 1 : 0;

        std::vector<int> matches(2 * n - 1, 0);
        for (int i = 0; i < 2 * n - 1; ++i) {
            int v1 = nums[i % n];
            int v2 = nums[(i + 1) % n];
            if (v1 == v2) matches[i] = 1;
        }

        int curr = 0;
        for (int i = 0; i < n - 1; ++i) curr += matches[i];
        int ans = (curr == k) ? 1 : 0;

        for (int i = 1; i < n; ++i) {
            curr += matches[i + n - 2] - matches[i - 1];
            if (curr == k) ans++;
        }
        return ans;
    }
};

